import { StatusBar } from "expo-status-bar";
import * as Location from "expo-location";
import * as SecureStore from "expo-secure-store";
import * as TaskManager from "expo-task-manager";
import { useEffect, useRef, useState } from "react";
import { ActivityIndicator, Animated, AppState, KeyboardAvoidingView, Linking, Platform, Pressable, RefreshControl, SafeAreaView, ScrollView, StyleSheet, Text, TextInput, View } from "react-native";

const API_URL=process.env.EXPO_PUBLIC_API_URL??"http://127.0.0.1:8000";const ACCESS="zchit_agent_access";const REFRESH="zchit_agent_refresh";const BACKGROUND_LOCATION_TASK="zchit-agent-background-location";
TaskManager.defineTask(BACKGROUND_LOCATION_TASK,async({data,error})=>{if(error||!data)return;const access=await SecureStore.getItemAsync(ACCESS);if(!access)return;const locations=(data as {locations:Location.LocationObject[]}).locations;for(const location of locations){await fetch(`${API_URL}/api/v1/agent/location`,{method:"POST",headers:{"Content-Type":"application/json",Authorization:`Bearer ${access}`},body:JSON.stringify({latitude:location.coords.latitude,longitude:location.coords.longitude,accuracy_meters:location.coords.accuracy,device_recorded_at:new Date(location.timestamp).toISOString()})}).catch(()=>undefined);}});
type Screen="splash"|"gps"|"login"|"dashboard";type Position={latitude:number;longitude:number;accuracy_meters:number|null;device_recorded_at:string};type Installment={schedule_id:number;installment_number:number;due_date:string;payable_amount:string;paid_amount:string;balance_amount:string;status:"paid"|"partial"|"late_due"|"due"|"upcoming";collectable:boolean};type Assignment={enrollment_id:number;member_id:number;member_code:string;member_name:string;mobile_number:string;address:string;group_id:number;group_code:string;scheme_name:string;installments:Installment[]};type Receipt={receipt_number:string;amount:string;collection_type:string};type CollectionRow={id:string;payment_id:number|null;advance_id:number|null;member_id:number;member_name:string;member_code:string;scheme_name:string;installment_number:number|null;collection_type:"regular"|"late"|"advance";amount:string;payment_date:string;payment_mode:string;reference_number:string|null;receipt_number:string;status:string;created_at:string};type AgentProfile={agent_id:number;employee_id:number;employee_code:string;full_name:string;date_of_birth:string|null;gender:string|null;blood_group:string|null;mobile_number:string;personal_email:string|null;official_email:string|null;current_address:string;department:string;designation:string;employment_type:string;work_mode:string;joining_date:string;status:string;kyc_status:string;emergency_contact_name:string;emergency_contact_relationship:string;emergency_contact_mobile:string};type CustomerSuggestion={id:number;name:string;member_code:string};type CollectionHistoryData={rows:CollectionRow[];total_amount:string;total_count:number;today_amount:string;today_count:number;customers:CustomerSuggestion[]};
export default function App(){const[screen,setScreen]=useState<Screen>("splash");const[token,setToken]=useState<string|null>(null);const[shiftActive,setShiftActive]=useState(false);const[agentName,setAgentName]=useState("");const[assignments,setAssignments]=useState<Assignment[]>([]);const[receipt,setReceipt]=useState<Receipt|null>(null);const[profile,setProfile]=useState<AgentProfile|null>(null);const[history,setHistory]=useState<CollectionHistoryData>({rows:[],total_amount:"0",total_count:0,today_amount:"0",today_count:0,customers:[]});const[error,setError]=useState("");const watch=useRef<Location.LocationSubscription|null>(null);const opacity=useRef(new Animated.Value(0)).current;useEffect(()=>{Animated.timing(opacity,{toValue:1,duration:650,useNativeDriver:true}).start();const timer=setTimeout(()=>void boot(),1900);return()=>clearTimeout(timer);},[]);useEffect(()=>{const sub=AppState.addEventListener("change",state=>{if(state==="active"&&screen!=="splash")void enforceGps();});return()=>sub.remove();},[screen]);useEffect(()=>{if(shiftActive&&token)void startTracking();else stopTracking();return stopTracking;},[shiftActive,token]);async function boot(){const enabled=await gpsReady();if(!enabled){setScreen("gps");return;}const saved=await SecureStore.getItemAsync(ACCESS);if(!saved){setScreen("login");return;}setToken(saved);try{const status=await api("/api/v1/agent/status",{},saved);setAgentName(status.employee_name);setShiftActive(status.shift_active);if(status.shift_active){const tasks=await api("/api/v1/agent/assignments",{},saved);setAssignments(tasks);}await Promise.all([loadHistory(saved),loadProfile(saved)]);setScreen("dashboard");}catch{await clearSession();setScreen("login");}}async function gpsReady(){const services=await Location.hasServicesEnabledAsync();const permission=await Location.getForegroundPermissionsAsync();return services&&permission.status==="granted";}async function enforceGps(){if(!await gpsReady())setScreen("gps");}async function requestGps(){const permission=await Location.requestForegroundPermissionsAsync();if(permission.status!=="granted"){setError("Location permission is required to use zChit Agent.");return;}if(!await Location.hasServicesEnabledAsync()){setError("Turn on device location services, then try again.");return;}setError("");setScreen(token?"dashboard":"login");}async function currentPosition():Promise<Position>{if(!await gpsReady())throw new Error("GPS must be enabled.");const location=await Location.getCurrentPositionAsync({accuracy:Location.Accuracy.High});return{latitude:location.coords.latitude,longitude:location.coords.longitude,accuracy_meters:location.coords.accuracy,device_recorded_at:new Date(location.timestamp).toISOString()};}async function api(path:string,init:RequestInit={},access=token){const response=await fetch(`${API_URL}${path}`,{...init,headers:{"Content-Type":"application/json",...(init.headers??{}),Authorization:`Bearer ${access}`}});const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.detail??"Request failed.");return body;}async function loadProfile(access=token){const data=await api("/api/v1/agent/profile",{},access);setProfile(data);return data;}async function refreshHome(){const status=await api("/api/v1/agent/status");setAgentName(status.employee_name);setShiftActive(status.shift_active);setAssignments(status.shift_active?await api("/api/v1/agent/assignments"):[]);await loadHistory();}async function loadHistory(access=token,query=""){const data=await api(`/api/v1/agent/collections${query}`,{},access);setHistory(data);return data;}async function finishLogin(body:{access_token:string;refresh_token?:string}){await SecureStore.setItemAsync(ACCESS,body.access_token);if(body.refresh_token)await SecureStore.setItemAsync(REFRESH,body.refresh_token);setToken(body.access_token);const status=await api("/api/v1/agent/status",{},body.access_token);setAgentName(status.employee_name);setShiftActive(status.shift_active);await Promise.all([loadHistory(body.access_token),loadProfile(body.access_token)]);setScreen("dashboard");}async function login(code:string,password:string){const response=await fetch(`${API_URL}/api/v1/auth/login`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({email:code.trim().toUpperCase(),password})});const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.detail??"Unable to sign in.");if(body.mfa_required&&body.challenge_token)return body.challenge_token;if(!body.access_token)throw new Error("Unable to create a secure session.");await finishLogin(body);return null;}async function verifyMfa(challenge:string,code:string){const response=await fetch(`${API_URL}/api/v1/auth/mfa/verify-login`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({challenge_token:challenge,code})});const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.detail??"Invalid security code.");await finishLogin(body);}async function checkIn(){try{const point=await currentPosition();const background=await Location.requestBackgroundPermissionsAsync();if(background.status!=="granted")throw new Error("Allow location all the time to start an agent shift.");await api("/api/v1/agent/check-in",{method:"POST",body:JSON.stringify(point)});setShiftActive(true);await startBackgroundTracking();setAssignments(await api("/api/v1/agent/assignments"));await loadHistory();}catch(reason){setError(reason instanceof Error?reason.message:"Unable to check in.");}}async function checkOut(){try{const point=await currentPosition();await api("/api/v1/agent/check-out",{method:"POST",body:JSON.stringify(point)});await stopBackgroundTracking();setShiftActive(false);setAssignments([]);await loadHistory();}catch(reason){setError(reason instanceof Error?reason.message:"Unable to check out.");}}async function startBackgroundTracking(){const available=await TaskManager.isAvailableAsync();if(!available)return;if(!await Location.hasStartedLocationUpdatesAsync(BACKGROUND_LOCATION_TASK)){await Location.startLocationUpdatesAsync(BACKGROUND_LOCATION_TASK,{accuracy:Location.Accuracy.High,timeInterval:15000,distanceInterval:20,pausesUpdatesAutomatically:false,showsBackgroundLocationIndicator:true,foregroundService:{notificationTitle:"zChit shift active",notificationBody:"Location tracking is active for your collection shift.",notificationColor:"#047857"}});}}async function stopBackgroundTracking(){if(await Location.hasStartedLocationUpdatesAsync(BACKGROUND_LOCATION_TASK))await Location.stopLocationUpdatesAsync(BACKGROUND_LOCATION_TASK);}async function startTracking(){stopTracking();watch.current=await Location.watchPositionAsync({accuracy:Location.Accuracy.High,timeInterval:15000,distanceInterval:20},location=>{void api("/api/v1/agent/location",{method:"POST",body:JSON.stringify({latitude:location.coords.latitude,longitude:location.coords.longitude,accuracy_meters:location.coords.accuracy,device_recorded_at:new Date(location.timestamp).toISOString()})}).catch(()=>undefined);});void startBackgroundTracking();}function stopTracking(){watch.current?.remove();watch.current=null;}async function collect(assignment:Assignment,installment:Installment|null,type:"regular"|"late"|"advance",amountType:"full"|"partial",amount:string,mode:string,reference:string,notes:string){const point=await currentPosition();const result=await api("/api/v1/agent/collections",{method:"POST",body:JSON.stringify({enrollment_id:assignment.enrollment_id,schedule_id:installment?.schedule_id??null,collection_type:type,amount_type:amountType,amount:Number(amount),payment_mode:mode,reference_number:reference||null,notes:notes||null,latitude:point.latitude,longitude:point.longitude,location_text:"Mobile GPS collection"})});setAssignments(await api("/api/v1/agent/assignments"));await loadHistory();setReceipt(result);}async function clearSession(){stopTracking();await stopBackgroundTracking();await SecureStore.deleteItemAsync(ACCESS);await SecureStore.deleteItemAsync(REFRESH);setToken(null);setShiftActive(false);setAssignments([]);setProfile(null);}async function logout(){await clearSession();setScreen("login");}if(screen==="splash")return <Splash opacity={opacity}/>;if(screen==="gps")return <GpsGate error={error} onEnable={requestGps}/>;if(screen==="login")return <LoginScreen error={error} setError={setError} onLogin={login} onVerifyMfa={verifyMfa}/>;return <Dashboard name={agentName} shiftActive={shiftActive} assignments={assignments} profile={profile} onLoadProfile={loadProfile} history={history} onRefreshHome={refreshHome} onLoadHistory={loadHistory} error={error} receipt={receipt} onCheckIn={checkIn} onCheckOut={checkOut} onCollect={collect} onDismissReceipt={()=>setReceipt(null)} onLogout={logout}/>;}
function Brand(){return <View style={s.brand}><Text style={s.brandText}>z</Text></View>}
function Splash({opacity}:{opacity:Animated.Value}){return <SafeAreaView style={s.splash}><StatusBar style="light"/><Animated.View style={{opacity,alignItems:"center"}}><Brand/><Text style={s.splashTitle}>zChit</Text><Text style={s.splashSub}>COLLECTION AGENT</Text><Text style={s.splashCaption}>Secure collections. Every route. Every receipt.</Text></Animated.View><ActivityIndicator style={s.loader} color="#a7f3d0"/></SafeAreaView>}
function GpsGate({error,onEnable}:{error:string;onEnable:()=>void}){return <SafeAreaView style={s.gate}><StatusBar style="dark"/><View style={s.gpsIcon}><Text style={s.gpsEmoji}>◎</Text></View><Text style={s.gateTitle}>Location required</Text><Text style={s.gateText}>zChit Agent works only while GPS is enabled. Location verifies attendance, live routes, and every collection receipt.</Text>{error?<Text style={s.error}>{error}</Text>:null}<Pressable style={s.primary} onPress={onEnable}><Text style={s.primaryText}>Enable GPS access</Text></Pressable><Pressable onPress={()=>Linking.openSettings()}><Text style={s.settingsLink}>Open device settings</Text></Pressable></SafeAreaView>}
function LoginScreen({error,setError,onLogin,onVerifyMfa}:{error:string;setError:(v:string)=>void;onLogin:(c:string,p:string)=>Promise<string|null>;onVerifyMfa:(challenge:string,code:string)=>Promise<void>}){const[code,setCode]=useState("");const[password,setPassword]=useState("");const[mfaCode,setMfaCode]=useState("");const[challenge,setChallenge]=useState<string|null>(null);const[loading,setLoading]=useState(false);async function submit(){setLoading(true);setError("");try{const value=await onLogin(code,password);if(value)setChallenge(value);}catch(reason){setError(reason instanceof Error?reason.message:"Unable to sign in.");}finally{setLoading(false);}}async function submitMfa(){if(!challenge)return;setLoading(true);setError("");try{await onVerifyMfa(challenge,mfaCode);}catch(reason){setError(reason instanceof Error?reason.message:"Unable to verify security code.");}finally{setLoading(false);}}return <SafeAreaView style={s.page}><StatusBar style="dark"/><KeyboardAvoidingView behavior={Platform.OS==="ios"?"padding":undefined} style={s.login}><View style={s.header}><Brand/><View><Text style={s.logoName}>zChit</Text><Text style={s.logoSub}>COLLECTION AGENT</Text></View></View><Text style={s.eyebrow}>{challenge?"SECURITY CHECK":"WELCOME BACK"}</Text><Text style={s.loginTitle}>{challenge?"Verify your identity":"Sign in to start your day"}</Text><Text style={s.description}>{challenge?"Enter the authenticator code or a recovery code for this account.":"Use the employee code and password provided by your administrator."}</Text><View style={s.card}>{challenge?<><Text style={s.label}>Security code</Text><TextInput value={mfaCode} onChangeText={setMfaCode} autoFocus autoCapitalize="characters" placeholder="000000 or recovery code" style={s.input}/>{error?<Text style={s.error}>{error}</Text>:null}<Pressable style={s.primary} onPress={submitMfa} disabled={loading}>{loading?<ActivityIndicator color="#fff"/>:<Text style={s.primaryText}>Verify and sign in</Text>}</Pressable><Pressable onPress={()=>{setChallenge(null);setMfaCode("");setError("");}}><Text style={s.settingsLink}>Back to password</Text></Pressable></>:<><Text style={s.label}>Employee code</Text><TextInput value={code} onChangeText={setCode} autoCapitalize="characters" placeholder="EMP-XXXXXXXX" style={s.input}/><Text style={[s.label,{marginTop:16}]}>Password</Text><TextInput value={password} onChangeText={setPassword} secureTextEntry placeholder="Enter your password" style={s.input}/>{error?<Text style={s.error}>{error}</Text>:null}<Pressable style={s.primary} onPress={submit} disabled={loading}>{loading?<ActivityIndicator color="#fff"/>:<Text style={s.primaryText}>Sign in securely</Text>}</Pressable></>}</View></KeyboardAvoidingView></SafeAreaView>}
function Dashboard({name,shiftActive,assignments,profile,onLoadProfile,history,onRefreshHome,onLoadHistory,error,receipt,onCheckIn,onCheckOut,onCollect,onDismissReceipt,onLogout}:{name:string;shiftActive:boolean;assignments:Assignment[];profile:AgentProfile|null;onLoadProfile:(access?:string|null)=>Promise<AgentProfile>;history:CollectionHistoryData;onRefreshHome:()=>Promise<void>;onLoadHistory:(access?:string|null,query?:string)=>Promise<CollectionHistoryData>;error:string;receipt:Receipt|null;onCheckIn:()=>void;onCheckOut:()=>void;onCollect:(a:Assignment,i:Installment|null,t:"regular"|"late"|"advance",amountType:"full"|"partial",amount:string,mode:string,reference:string,notes:string)=>Promise<void>;onDismissReceipt:()=>void;onLogout:()=>void}){const[selected,setSelected]=useState<Assignment|null>(null);const[view,setView]=useState<"home"|"collections"|"profile">("home");const[drawerOpen,setDrawerOpen]=useState(false);const[refreshing,setRefreshing]=useState(false);async function refresh(){setRefreshing(true);try{await onRefreshHome();}finally{setRefreshing(false);}}if(view==="collections")return <CollectionHistoryScreen data={history} onLoad={onLoadHistory} onMenu={()=>setDrawerOpen(true)} drawer={drawerOpen?<AgentDrawer name={name} active={view} onNavigate={next=>{setDrawerOpen(false);setView(next);}} onClose={()=>setDrawerOpen(false)} onLogout={onLogout}/>:null}/>;if(view==="profile")return <AgentProfileScreen profile={profile} onRefresh={onLoadProfile} onMenu={()=>setDrawerOpen(true)} drawer={drawerOpen?<AgentDrawer name={name} active={view} onNavigate={next=>{setDrawerOpen(false);setView(next);}} onClose={()=>setDrawerOpen(false)} onLogout={onLogout}/>:null}/>;return <SafeAreaView style={s.page}><StatusBar style="dark"/><View style={s.appHeader}><View style={s.headerLeft}><Pressable style={s.headerButton} onPress={()=>setDrawerOpen(true)}><Text style={s.hamburger}>☰</Text></Pressable><View style={s.headerBrand}><View style={s.miniBrand}><Text style={s.miniBrandText}>z</Text></View><View><Text style={s.headerTitle}>zChit</Text><Text style={s.headerSubtitle}>AGENT</Text></View></View></View><Pressable style={s.headerButton} onPress={()=>{}}><View style={s.bellIcon}><View style={s.bellDome}/><View style={s.bellClapper}/></View><View style={s.notificationDot}/></Pressable></View><View style={s.welcomeRow}><View><Text style={s.dashHello}>Hello, {name||"Agent"}</Text><Text style={s.dashDate}>{new Date().toLocaleDateString("en-IN",{weekday:"long",day:"numeric",month:"long"})}</Text></View><View style={[s.onlineBadge,shiftActive&&s.onlineActive]}><View style={[s.onlineDot,shiftActive&&s.onlineDotActive]}/><Text style={[s.onlineText,shiftActive&&s.onlineTextActive]}>{shiftActive?"On duty":"Off duty"}</Text></View></View><ScrollView contentContainerStyle={s.scroll} refreshControl={<RefreshControl refreshing={refreshing} onRefresh={refresh} colors={["#059669"]} tintColor="#059669"/>}><View style={[s.shiftCard,shiftActive?s.shiftActive:s.shiftOff]}><View><Text style={s.shiftLabel}>{shiftActive?"SHIFT ACTIVE":"NOT CHECKED IN"}</Text><Text style={s.shiftTitle}>{shiftActive?"Live GPS tracking is on":"Check in to view members"}</Text><Text style={s.shiftText}>{shiftActive?"Your location updates during the active shift.":"GPS attendance is required before collections."}</Text></View><Pressable style={[s.shiftButton,shiftActive&&s.checkout]} onPress={shiftActive?onCheckOut:onCheckIn}><Text style={s.shiftButtonText}>{shiftActive?"Check out":"Check in"}</Text></Pressable></View>{error?<Text style={s.error}>{error}</Text>:null}<View style={s.todayCard}><View><Text style={s.todayLabel}>TODAY COLLECTED</Text><Text style={s.todayAmount}>₹{Number(history.today_amount).toLocaleString("en-IN")}</Text><Text style={s.todayCount}>{history.today_count} collection{history.today_count===1?"":"s"} today</Text></View><Pressable style={s.viewAllButton} onPress={()=>setView("collections")}><Text style={s.viewAllText}>View all</Text></Pressable></View><View style={s.sectionRow}><Text style={s.sectionTitle}>Assigned collections</Text><Text style={s.count}>{shiftActive?assignments.length:0}</Text></View>{!shiftActive?<Empty text="Member access unlocks after GPS check-in."/>:assignments.length===0?<Empty text="No members assigned for collection."/>:assignments.map(item=><Pressable key={item.enrollment_id} style={s.memberCard} onPress={()=>setSelected(item)}><View style={s.avatar}><Text style={s.avatarText}>{item.member_name[0]}</Text></View><View style={{flex:1}}><Text style={s.memberName}>{item.member_name}</Text><Text style={s.memberMeta}>{item.member_code} · {item.scheme_name}</Text><Text style={s.memberMeta}>{item.mobile_number}</Text></View><View style={s.balance}><Text style={s.balanceLabel}>DUE</Text><Text style={s.balanceValue}>₹{item.installments.reduce((sum,i)=>sum+Number(i.balance_amount),0).toLocaleString("en-IN")}</Text></View></Pressable>)}</ScrollView>{selected?<CollectionPanel assignment={selected} onClose={()=>setSelected(null)} onCollect={onCollect}/>:null}{receipt?<ReceiptPanel receipt={receipt} onClose={onDismissReceipt}/>:null}{drawerOpen?<AgentDrawer name={name} active={view} onNavigate={next=>{setDrawerOpen(false);setView(next);}} onClose={()=>setDrawerOpen(false)} onLogout={onLogout}/>:null}</SafeAreaView>}

function AgentDrawer({name,active,onNavigate,onClose,onLogout}:{name:string;active:"home"|"collections"|"profile";onNavigate:(view:"home"|"collections"|"profile")=>void;onClose:()=>void;onLogout:()=>void}){const items:["home"|"collections"|"profile",string,string][]=[["home","⌂","Home"],["collections","₹","Collections"],["profile","◎","Profile"]];return <View style={s.drawerOverlay}><Pressable style={s.drawerBackdrop} onPress={onClose}/><View style={s.drawer}><View style={s.drawerHeader}><View style={s.drawerBrand}><Text style={s.drawerBrandText}>z</Text></View><View><Text style={s.drawerApp}>zChit Agent</Text><Text style={s.drawerName}>{name||"Collection agent"}</Text></View></View><View style={s.drawerMenu}>{items.map(([value,icon,label])=><Pressable key={value} onPress={()=>onNavigate(value)} style={[s.drawerItem,active===value&&s.drawerItemActive]}><Text style={[s.drawerIcon,active===value&&s.drawerItemTextActive]}>{icon}</Text><Text style={[s.drawerItemText,active===value&&s.drawerItemTextActive]}>{label}</Text></Pressable>)}</View><Pressable style={s.drawerLogout} onPress={onLogout}><Text style={s.drawerLogoutIcon}>↪</Text><Text style={s.drawerLogoutText}>Logout</Text></Pressable></View></View>}

function AgentProfileScreen({profile,onRefresh,onMenu,drawer}:{profile:AgentProfile|null;onRefresh:(access?:string|null)=>Promise<AgentProfile>;onMenu:()=>void;drawer:React.ReactNode}){const[refreshing,setRefreshing]=useState(false);async function refresh(){setRefreshing(true);try{await onRefresh();}finally{setRefreshing(false);}}const fields=profile?[["Employee code",profile.employee_code],["Department",profile.department],["Designation",profile.designation],["Employment type",profile.employment_type],["Work mode",profile.work_mode],["Joining date",new Date(profile.joining_date+"T00:00:00").toLocaleDateString("en-IN")],["Mobile",profile.mobile_number],["Email",profile.official_email||profile.personal_email||"Not provided"],["Gender",profile.gender||"Not provided"],["Blood group",profile.blood_group||"Not provided"],["KYC status",profile.kyc_status.toUpperCase()],["Current address",profile.current_address],["Emergency contact",profile.emergency_contact_name+" · "+profile.emergency_contact_relationship],["Emergency mobile",profile.emergency_contact_mobile]]:[];return <SafeAreaView style={s.page}><StatusBar style="dark"/><View style={s.profileHeader}><Pressable style={s.headerButton} onPress={onMenu}><Text style={s.hamburger}>☰</Text></Pressable><View><Text style={s.historyTitle}>Profile</Text><Text style={s.historySubtitle}>Employee details</Text></View></View><ScrollView contentContainerStyle={s.profileScroll} refreshControl={<RefreshControl refreshing={refreshing} onRefresh={refresh} colors={["#059669"]} tintColor="#059669"/>}>{profile?<><View style={s.profileHero}><View style={s.profileAvatar}><Text style={s.profileAvatarText}>{profile.full_name[0]}</Text></View><Text style={s.profileName}>{profile.full_name}</Text><Text style={s.profileRole}>{profile.designation} · {profile.department}</Text><View style={s.profileStatus}><Text style={s.profileStatusText}>{profile.status.toUpperCase()}</Text></View></View><View style={s.profileDetails}>{fields.map(([label,value])=><View key={label} style={s.profileRow}><Text style={s.profileLabel}>{label}</Text><Text style={s.profileValue}>{value}</Text></View>)}</View></>:<ActivityIndicator style={{marginTop:40}} color="#059669"/>}</ScrollView>{drawer}</SafeAreaView>}

function CollectionHistoryScreen({data,onLoad,onMenu,drawer}:{data:CollectionHistoryData;onLoad:(access?:string|null,query?:string)=>Promise<CollectionHistoryData>;onMenu:()=>void;drawer:React.ReactNode}){const[dateFrom,setDateFrom]=useState("");const[dateTo,setDateTo]=useState("");const[customer,setCustomer]=useState("");const[showSuggestions,setShowSuggestions]=useState(false);const[loading,setLoading]=useState(false);const[filterError,setFilterError]=useState("");const[refreshing,setRefreshing]=useState(false);const suggestions=customer.trim()?data.customers.filter(item=>item.name.toLowerCase().includes(customer.trim().toLowerCase())).slice(0,6):data.customers.slice(0,6);function filterQuery(){const params=new URLSearchParams();if(dateFrom)params.set("date_from",dateFrom);if(dateTo)params.set("date_to",dateTo);if(customer.trim())params.set("customer",customer.trim());return params.toString()?"?"+params.toString():"";}async function refresh(){setRefreshing(true);try{await onLoad(undefined,filterQuery());}finally{setRefreshing(false);}}async function applyFilters(){setLoading(true);setFilterError("");try{await onLoad(undefined,filterQuery());setShowSuggestions(false);}catch(reason){setFilterError(reason instanceof Error?reason.message:"Unable to load collections.");}finally{setLoading(false);}}async function clearFilters(){setDateFrom("");setDateTo("");setCustomer("");setShowSuggestions(false);setLoading(true);try{await onLoad();}finally{setLoading(false);}}return <SafeAreaView style={s.page}><StatusBar style="dark"/><View style={s.historyHeader}><Pressable onPress={onMenu} style={s.headerButton}><Text style={s.hamburger}>☰</Text></Pressable><View><Text style={s.historyTitle}>Collections</Text><Text style={s.historySubtitle}>Your collected receipts</Text></View></View><ScrollView contentContainerStyle={s.historyScroll} keyboardShouldPersistTaps="handled" refreshControl={<RefreshControl refreshing={refreshing} onRefresh={refresh} colors={["#059669"]} tintColor="#059669"/>}><View style={s.historySummary}><View><Text style={s.historySummaryLabel}>FILTERED TOTAL</Text><Text style={s.historySummaryAmount}>₹{Number(data.total_amount).toLocaleString("en-IN")}</Text></View><Text style={s.historySummaryCount}>{data.total_count} receipts</Text></View><View style={s.filterCard}><Text style={s.filterTitle}>Filter collections</Text><View style={s.dateRow}><View style={s.dateField}><Text style={s.label}>From date</Text><TextInput value={dateFrom} onChangeText={setDateFrom} placeholder="YYYY-MM-DD" style={s.filterInput}/></View><View style={s.dateField}><Text style={s.label}>To date</Text><TextInput value={dateTo} onChangeText={setDateTo} placeholder="YYYY-MM-DD" style={s.filterInput}/></View></View><Text style={[s.label,{marginTop:8}]}>Customer name</Text><TextInput value={customer} onFocus={()=>setShowSuggestions(true)} onChangeText={value=>{setCustomer(value);setShowSuggestions(true);}} placeholder="Start typing customer name" style={s.filterInput}/>{showSuggestions&&suggestions.length?<View style={s.suggestions}>{suggestions.map(item=><Pressable key={item.id} onPress={()=>{setCustomer(item.name);setShowSuggestions(false);}} style={s.suggestionRow}><Text style={s.suggestionName}>{item.name}</Text><Text style={s.suggestionCode}>{item.member_code}</Text></Pressable>)}</View>:null}{filterError?<Text style={s.error}>{filterError}</Text>:null}<View style={s.filterActions}><Pressable onPress={clearFilters} style={s.clearButton}><Text style={s.clearButtonText}>Clear</Text></Pressable><Pressable onPress={applyFilters} disabled={loading} style={s.applyButton}>{loading?<ActivityIndicator color="#fff"/>:<Text style={s.applyButtonText}>Apply filters</Text>}</Pressable></View></View><View style={s.sectionRow}><Text style={s.sectionTitle}>Collected list</Text><Text style={s.count}>{data.total_count}</Text></View>{data.rows.length===0?<Empty text="No collections match these filters."/>:data.rows.map(item=><View key={item.id} style={s.collectionCard}><View style={s.collectionTop}><View style={s.collectionAvatar}><Text style={s.collectionAvatarText}>{item.member_name[0]}</Text></View><View style={{flex:1}}><Text style={s.collectionName}>{item.member_name}</Text><Text style={s.collectionMeta}>{item.member_code} · {item.scheme_name}</Text></View><Text style={s.collectionAmount}>₹{Number(item.amount).toLocaleString("en-IN")}</Text></View><View style={s.collectionDetails}><Text style={s.collectionDetail}>{item.installment_number?"Installment #"+item.installment_number:"General advance"}</Text><Text style={s.collectionDetail}>{item.collection_type.toUpperCase()} · {item.payment_mode.toUpperCase()}</Text><Text style={s.collectionDetail}>{new Date(item.payment_date+"T00:00:00").toLocaleDateString("en-IN")}</Text></View><Text style={s.collectionReceipt}>{item.receipt_number}</Text></View>)}</ScrollView>{drawer}</SafeAreaView>}

function CollectionPanel({assignment,onClose,onCollect}:{assignment:Assignment;onClose:()=>void;onCollect:(a:Assignment,i:Installment|null,t:"regular"|"late"|"advance",amountType:"full"|"partial",amount:string,mode:string,reference:string,notes:string)=>Promise<void>}){
const installments=[...assignment.installments].sort((a,b)=>a.installment_number-b.installment_number||a.due_date.localeCompare(b.due_date));
const[installment,setInstallment]=useState<Installment|null>(null);const[type,setType]=useState<"regular"|"late"|"advance">("regular");const[amountType,setAmountType]=useState<"full"|"partial">("full");const[amount,setAmount]=useState("");const[mode,setMode]=useState("cash");const[reference,setReference]=useState("");const[notes,setNotes]=useState("");const[loading,setLoading]=useState(false);const[error,setError]=useState("");
function suggestedType(item:Installment):"regular"|"late"|"advance"{const due=new Date(`${item.due_date}T00:00:00`);const now=new Date();const dueMonth=due.getFullYear()*12+due.getMonth();const currentMonth=now.getFullYear()*12+now.getMonth();return dueMonth>currentMonth?"advance":dueMonth<currentMonth?"late":"regular";}
function choose(item:Installment){if(item.status==="paid")return;const nextType=suggestedType(item);setInstallment(item);setType(nextType);setAmountType("full");setAmount(item.balance_amount);setMode("cash");setReference("");setNotes("");setError("");}
function backToInstallments(){setInstallment(null);setError("");}
function chooseAmount(value:"full"|"partial"){setAmountType(value);if(value==="full"&&installment)setAmount(installment.balance_amount);else setAmount("");}
function chooseType(value:"regular"|"late"|"advance"){setType(value);setAmountType("full");if(installment)setAmount(installment.balance_amount);}
async function submit(){if(!installment){setError("Select an installment first.");return;}if(!amount||Number(amount)<=0){setError("Enter a valid amount.");return;}setLoading(true);try{await onCollect(assignment,installment,type,amountType,amount,mode,reference,notes);onClose();}catch(reason){setError(reason instanceof Error?reason.message:"Unable to collect.");}finally{setLoading(false);}}
return <View style={s.overlay}><View style={s.panel}><View style={s.panelHeader}><View><Text style={s.panelTitle}>{assignment.member_name}</Text><Text style={s.panelSub}>{assignment.member_code} · {assignment.scheme_name}</Text></View><Pressable onPress={onClose}><Text style={s.close}>×</Text></Pressable></View>
{!installment?<ScrollView><Text style={s.label}>Choose an installment to collect</Text><Text style={s.listHint}>Tap the installment amount to open its collection form.</Text>{installments.map(item=><Pressable key={item.schedule_id} onPress={()=>choose(item)} disabled={item.status==="paid"} style={[s.installment,item.status==="paid"&&s.installmentDisabled]}><View><Text style={s.installmentText}>Installment #{item.installment_number} · {new Date(item.due_date).toLocaleDateString("en-IN")}</Text><Text style={s.installmentSub}>Payable ₹{Number(item.payable_amount).toLocaleString("en-IN")} · Paid ₹{Number(item.paid_amount).toLocaleString("en-IN")}</Text></View><View style={s.installmentRight}><Text style={[s.statusChip,item.status==="paid"&&s.statusPaid,item.status==="late_due"&&s.statusLate,item.status==="due"&&s.statusDue,item.status==="partial"&&s.statusPartial]}>{item.status.replaceAll("_"," ").toUpperCase()}</Text><Text style={s.installmentAmount}>₹{Number(item.balance_amount).toLocaleString("en-IN")}</Text><Text style={s.tapLabel}>{item.status==="paid"?"Completed":"Tap to collect"}</Text></View></Pressable>)}</ScrollView>:
<ScrollView><Pressable onPress={backToInstallments} style={s.backAction}><Text style={s.backActionText}>‹ Back to installments</Text></Pressable><View style={s.selectedInstallment}><View><Text style={s.selectedEyebrow}>COLLECTING AGAINST</Text><Text style={s.selectedTitle}>Installment #{installment.installment_number}</Text><Text style={s.selectedDate}>Due {new Date(installment.due_date).toLocaleDateString("en-IN")}</Text></View><View style={s.selectedBalance}><Text style={s.selectedBalanceLabel}>BALANCE</Text><Text style={s.selectedBalanceAmount}>₹{Number(installment.balance_amount).toLocaleString("en-IN")}</Text></View></View>
<Text style={[s.label,{marginTop:16}]}>Collection type</Text><View style={s.segment}>{(["regular","late","advance"] as const).map(value=><Pressable key={value} onPress={()=>chooseType(value)} style={[s.segmentItem,type===value&&s.segmentActive]}><Text style={[s.segmentText,type===value&&s.segmentTextActive]}>{value.toUpperCase()}</Text></Pressable>)}</View>
<Text style={[s.label,{marginTop:14}]}>Amount option</Text><View style={s.segment}>{(["full","partial"] as const).map(value=><Pressable key={value} onPress={()=>chooseAmount(value)} style={[s.segmentItem,amountType===value&&s.segmentActive]}><Text style={[s.segmentText,amountType===value&&s.segmentTextActive]}>{value.toUpperCase()}</Text></Pressable>)}</View>
<Text style={[s.label,{marginTop:14}]}>Amount</Text><TextInput value={amount} editable={amountType==="partial"} onChangeText={setAmount} keyboardType="decimal-pad" placeholder="0.00" style={[s.input,amountType==="full"&&s.readonlyInput]}/><Text style={[s.label,{marginTop:14}]}>Payment mode</Text><View style={s.modeRow}>{["cash","upi","bank","cheque"].map(value=><Pressable key={value} onPress={()=>setMode(value)} style={[s.mode,mode===value&&s.modeActive]}><Text style={[s.modeText,mode===value&&s.modeTextActive]}>{value.toUpperCase()}</Text></Pressable>)}</View><Text style={[s.label,{marginTop:14}]}>Reference</Text><TextInput value={reference} onChangeText={setReference} placeholder="Optional for cash" style={s.input}/><Text style={[s.label,{marginTop:14}]}>Notes</Text><TextInput value={notes} onChangeText={setNotes} placeholder="Optional collection notes" style={s.input}/>{error?<Text style={s.error}>{error}</Text>:null}<Pressable onPress={submit} disabled={loading} style={[s.primary,s.fullWidthAction]}>{loading?<ActivityIndicator color="#fff"/>:<Text style={s.primaryText}>Collect installment #{installment.installment_number}</Text>}</Pressable></ScrollView>}
</View></View>}

function ReceiptPanel({receipt,onClose}:{receipt:Receipt;onClose:()=>void}){return <View style={s.overlay}><View style={s.receipt}><View style={s.success}><Text style={s.successText}>✓</Text></View><Text style={s.receiptTitle}>Collection recorded</Text><Text style={s.receiptAmount}>₹{Number(receipt.amount).toLocaleString("en-IN")}</Text><Text style={s.receiptNo}>{receipt.receipt_number}</Text><Text style={s.receiptType}>{receipt.collection_type.toUpperCase()} RECEIPT</Text><Pressable onPress={onClose} style={[s.primary,s.fullWidthAction]}><Text style={s.primaryText}>Done</Text></Pressable></View></View>}
function Empty({text}:{text:string}){return <View style={s.empty}><Text style={s.emptyIcon}>◎</Text><Text style={s.emptyText}>{text}</Text></View>}
